- (void)mouseExited:(NSEvent*)event{[self.tooltip hide];[self.hoverView hide];[self.effectsLayer hideSlot:nil];self.hoverSlot=nil;[self refreshPicked];self.needsDisplay=YES;}
- (void)mouseMoved:(NSEvent*)event{auto point=[self convertPoint:event.locationInWindow fromView:nil];point.x*=190/self.bounds.size.width;point.y*=429/self.bounds.size.height;if(slots)for(auto& pair:*slots)if(pair.first<120){auto& item=catalog->at(pair.second.index);if(NSPointInRect(point,NSMakeRect(15+(pair.first%8)*20,(self.shopMode?50:36)+(pair.first/8)*20,item.width*20,item.height*20))){CGFloat factor=self.bounds.size.width/190;NSRect itemRect=NSMakeRect((15+(pair.first%8)*20)*factor,((self.shopMode?50:36)+(pair.first/8)*20)*factor,item.width*20*factor,item.height*20*factor);if(!self.hoverView)self.hoverView=[MuHoveredItemView new];[self.hoverView showItem:pair.second root:self.assetRoot.UTF8String language:self.language.UTF8String rect:itemRect inView:self];if(![self.hoverSlot isEqualToNumber:@(pair.first)])self.needsDisplay=YES;self.hoverSlot=@(pair.first);[self.effectsLayer hideSlot:self.hoverSlot];if(!self.tooltip)self.tooltip=[MuItemTooltip new];auto cursor=[self.superview convertPoint:event.locationInWindow fromView:nil];auto requirements=self.dragController?[self.dragController attributes]:mu::client::EquipmentAttributes{};[self.tooltip showStyledText:mu::ui::item_tooltip_styled(pair.second,*catalog,texts,self.bounds.size.width/190,requirements.ready?&requirements:nullptr) atPoint:cursor inView:self.superview scale:self.bounds.size.width/190];return;}}[self.tooltip hide];[self.hoverView hide];[self.effectsLayer hideSlot:nil];self.hoverSlot=nil;self.needsDisplay=YES;}
