@implementation MuWarehousePanel{BOOL notified;}
- (instancetype)initWithState:(const mu::client::NpcState&)state assetRoot:(const std::string&)root language:(const std::string&)language{
 self=[super init];if(!self)return nil;auto directory=std::filesystem::path(root)/"Data/Interface";
 NSMutableDictionary* images=[NSMutableDictionary dictionary];const char* keys[]={"back","top","left","right","bottom","money","cell","deposit","withdraw","lock"};const char* files[]={"newui_msgbox_back.jpg","newui_item_back01.tga","newui_item_back02-L.tga","newui_item_back02-R.tga","newui_item_back03.tga","newui_item_money3.tga","newui_item_box.tga","newui_Bt_money01.tga","newui_Bt_money02.tga",state.lockState?"newui_Bt_lock.tga":"newui_Bt_lock02.tga"};for(unsigned i=0;i<10;i++)images[[NSString stringWithUTF8String:keys[i]]]=mu::viewer::load_interface_image(directory,files[i]);
