 NSMutableArray* entries=[NSMutableArray arrayWithCapacity:240];for(unsigned i=0;i<240;i++)[entries addObject:@""];
 auto definitions=mu::ui::load_item_catalog(std::filesystem::path(root)/"Data",language);if(state.items)for(auto& pair:*state.items)entries[pair.first]=mu::ui::item_name(pair.second,*definitions);
 images[@"exit"]=mu::viewer::load_interface_image(directory,"newui_exit_00.tga");images[@"repair"]=mu::viewer::load_interface_image(directory,"newui_repair_00.tga");auto view=[[MuWarehouseView alloc] initWithFrame:NSMakeRect(0,0,190,429)];view.shopMode=state.result==0;view.repairAllowed=state.npcClass==243||state.npcClass==246||state.npcClass==251||state.npcClass==416||state.npcClass==578;if(view.shopMode)images[@"top"]=mu::viewer::load_interface_image(directory,"newui_item_back04.tga");view.images=images;view.assetRoot=[NSString stringWithUTF8String:root.c_str()];view.language=[NSString stringWithUTF8String:language.c_str()];view.entries=entries;[view setItems:state.items catalog:definitions texts:texts];view.locked=state.lockState!=0;view.titleText=[NSString stringWithFormat:@"%@ (%@)",localized(234),localized(state.lockState?241:240)];if(view.shopMode)view.titleText=localized(230);view.feeText=localized(266);auto gold=mu::ui::format_gold(view.shopMode?state.inventoryMoney:state.warehouseMoney);view.balance=state.moneyReady?[NSString stringWithUTF8String:gold.c_str()]:@"…";auto color=mu::ui::gold_color(state.warehouseMoney);view.balanceColor=[NSColor colorWithRed:color[0]/255. green:color[1]/255. blue:color[2]/255. alpha:1];__weak MuWarehousePanel* owner=self;view.closeHandler=^{[owner close];};view.buyHandler=^(unsigned slot){if(owner.onBuy)owner.onBuy(slot);};view.repairModeHandler=^(BOOL enabled){if(owner.onRepairMode)owner.onRepairMode(enabled);};view.repairAllHandler=^{if(owner.onRepairAll)owner.onRepairAll();};self.view=view;return self;
}
- (void)attachToGameView:(NSView*)game{[self attachToGameView:game rightOffset:0];}
